questionvariables.text:
funcidx: rand(3);   /* 0 sin, 1 cos, 2 tan */
/* Option values are neutral literals so the page source does not reveal the answer */
opts: [["f1", is(funcidx=0), "y = sin(x)"], ["f2", is(funcidx=1), "y = cos(x)"], ["f3", is(funcidx=2), "y = tan(x)"]];
ta_tex: if funcidx = 0 then sin(x) elseif funcidx = 1 then cos(x) else tan(x);
